public str getName()
{
    return fieldPName(InventDim, InventDimension3);
}

public Set getAllowedValues()
{
    var ret = new Set(Types::String);
    InventDim inventDim;
    while select InventDimension3 from inventDim
        group by InventDimension3
    {
        ret.add(inventDim.InventDimension3);
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(InventDim, InventDimension3));
    qbr.value(queryValue(_value));
}
